description:
Implement the Verilog module based on the following description.
We want to create a module that:

// (1) receives a 4-bit binary number,
// (2) checks if the number is odd,
// (3) counts the number of 0s in the binary number,
// (4) outputs a flag if the number is a power of 2,
// (5) provides a reset mechanism to reset all outputs.

// The input binary number is available on the input signal 'binary_num'. The output 'is_odd' should be set to 1 if the number is odd and 0 otherwise. The number of 0s in the binary number should be output on 'count_zeros[2:0]'. The power of 2 flag should be set on 'is_power_of_2' if the number is a power of 2. The reset signal is active high synchronous.

module top_module(
    input wire clk,
    input wire reset,
    input wire [3:0] binary_num,
    output reg is_odd,
    output reg [2:0] count_zeros,
    output reg is_power_of_2
);

code:
module top_module(
    input wire clk,
    input wire reset,
    input wire [3:0] binary_num,
    output reg is_odd,
    output reg [2:0] count_zeros,
    output reg is_power_of_2
);

    integer i;

    always @(posedge clk) begin
        if (reset) begin
            is_odd <= 0;
            count_zeros <= 0;
            is_power_of_2 <= 0;
        end else begin
            // Check if odd
            is_odd <= binary_num[0];

            // Count number of 0s
            count_zeros <= 0;
            for (i = 0; i < 4; i = i + 1) begin
                if (~binary_num[i]) begin
                    count_zeros <= count_zeros + 1;
                end
            end

            // Check if power of 2
            is_power_of_2 <= (binary_num != 0) && ((binary_num & (binary_num - 1)) == 0);
        end
    end

endmodule

