			state <= S0;
		else begin
			case (state)
				S0: state <= x ? S1 : S0;
				S1: state <= x ? S1 : S2;
				S2: state <= x ? S1 : S0;
			endcase
		end
	end

	assign z = (state == S2 && x==0);

endmodule

