module fsm_process (
        input clk,
        input rst,
        input go,
        input done,
        output reg out);

    parameter INIT = 0, PROCESS = 1, COMPLETE = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= INIT;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            INIT: next_state = go ? PROCESS : INIT;
            PROCESS: next_state = done ? COMPLETE : PROCESS;
            COMPLETE: next_state = rst ? INIT : COMPLETE;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == PROCESS) || (state == COMPLETE);

endmodule

