description:
Design a 4-bit pipelined Johnson counter that operates on the rising edge of the clock signal. It incorporates an asynchronous reset for initializing the counter to zero. The counter's output, Q, is calculated by performing a bitwise XOR operation on the values of four internal registers (Q1, Q2, Q3, and Q4), negating the result to generate the new state. This configuration allows for a sequential feedback mechanism that produces a specific counting sequence, leveraging pipeline stages to improve timing and throughput.
module top_module(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);

code:
module top_module(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);reg [3:0] Q1, Q2, Q3, Q4;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      Q1 <= 4'b0000;
      Q2 <= 4'b0000;
      Q3 <= 4'b0000;
      Q4 <= 4'b0000;
      Q  <= 4'b0000;
    end
    else begin
      Q1 <= Q;
      Q2 <= Q1;
      Q3 <= Q2;
      Q4 <= Q3;
      Q  <= ~(Q1 ^ Q2 ^ Q3 ^ Q4);
    end
  end

endmodule

