description:
Design a circuit that generates a 1Hz pulse from a 100MHz clock input. The module counts clock cycles up to 100 million before resetting and producing a high output pulse for one clock cycle. When the count reaches the specified maximum, it resets the counter and sets the output pulse to high, otherwise, it increments the count and keeps the output low.
module top_module(
    input clk_100MHz,
    output reg clk_pulse_1Hz
    );

code:
module top_module(
    input clk_100MHz,
    output reg clk_pulse_1Hz
    );parameter countMax=99999999;
    reg [26:0] count;
    always @(posedge clk_100MHz)
        if(count==countMax)
            begin
                count<=0;
                clk_pulse_1Hz<=1;
            end
        else
            begin
                count<=count+1;
                clk_pulse_1Hz<=0;
            end
endmodule

