code:
module top_module(
	input [3:0] A,
	input [3:0] B,
	output reg A_gt_B,
	output reg A_eq_B,
	output reg A_lt_B);always @(*) begin
	if (A > B) begin
		A_gt_B = 1;
		A_eq_B = 0;
		A_lt_B = 0;
	end else if (A < B) begin
		A_gt_B = 0;
		A_eq_B = 0;
		A_lt_B = 1;
	end else begin
		A_gt_B = 0;
		A_eq_B = 1;
		A_lt_B = 0;
	end
end
endmodule

