module fsm_module (
        input clk,
        input reset,
        input signal,
        output reg out);parameter R0=0, R1=1, R2=2, R3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= R0;
		else state <= next;

	always_comb begin
		case (state)
			R0: next = signal ? R1 : R0;
			R1: next = signal ? R2 : R1;
			R2: next = signal ? R3 : R2;
			R3: next = signal ? R0 : R3;
			default: next = 'x;
		endcase
	end

	assign out = (state == R1) || (state == R3);

endmodule

